/**
 * An independent check of contracts/canonical/vectors.json.
 *
 * The vectors are generated by a Python script. This re-derives every canonical
 * string and hash in a different runtime, with a different JSON writer, and
 * compares. If Node and Python disagree about what "keys sorted by code point,
 * no whitespace, every value a string, NFC-normalised" means, that disagreement
 * shows up here rather than on a real device at the M2 checkpoint, when a
 * fingerprint-signed approval mysteriously fails to verify.
 *
 * This is not a substitute for Prajit's Kotlin and Python implementations both
 * passing the vectors. It is the cheap check that the vectors themselves are
 * reproducible, and that the rules are written clearly enough for a second
 * implementation to follow from the spec alone.
 *
 * The implementation below is deliberately written from the build plan's wording
 * rather than ported from the generator, so that it can actually disagree.
 */

import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const here = path.dirname(fileURLToPath(import.meta.url));
const VECTORS_FILE = path.resolve(here, '../../../contracts/canonical/vectors.json');

const FIELDS = [
  'amount_paise',
  'currency',
  'expires_at',
  'initiator',
  'intent_id',
  'invoice_sha256',
  'nonce',
  'payee_account',
  'payee_ifsc',
  'payee_name',
  'payer_account',
  'purpose',
  'v',
];

/** Human-written text is NFC-normalised; identifiers and numbers are not. */
const TEXT_FIELDS = new Set(['payee_name', 'purpose']);

/** The canonical summary, built from the spec rather than from the generator. */
function canonical(payment) {
  const keys = Object.keys(payment).sort(); // JS sorts strings by code unit; see the test below.
  const parts = keys.map((key) => {
    const raw = payment[key];
    const value = TEXT_FIELDS.has(key) ? raw.normalize('NFC') : raw;
    return `${JSON.stringify(key)}:${JSON.stringify(value)}`;
  });
  return `{${parts.join(',')}}`;
}

function sha256Hex(text) {
  return createHash('sha256').update(Buffer.from(text, 'utf8')).digest('hex');
}

const vectors = JSON.parse(readFileSync(VECTORS_FILE, 'utf8'));

describe('the vectors file itself', () => {
  it('has the ten cases the build plan asks for, at least', () => {
    expect(vectors.length).toBeGreaterThanOrEqual(10);
  });

  it('covers the three cases the build plan names by name', () => {
    const names = vectors.map((v) => v.name);
    expect(names).toContain('tamil_payee_name');
    expect(names).toContain('crore_sized_amount');
    expect(names).toContain('account_with_leading_zeros');
  });

  it('gives every vector a name, a description and a payment', () => {
    for (const v of vectors) {
      expect(typeof v.name).toBe('string');
      expect(v.description.length).toBeGreaterThan(10);
      expect(typeof v.payment).toBe('object');
    }
  });

  it('has no duplicate names', () => {
    const names = vectors.map((v) => v.name);
    expect(new Set(names).size).toBe(names.length);
  });
});

describe('every value is a string, and every field is present', () => {
  it.each(vectors.map((v) => [v.name, v]))('%s', (_name, v) => {
    expect(Object.keys(v.payment).sort()).toEqual([...FIELDS].sort());
    for (const [key, value] of Object.entries(v.payment)) {
      expect(typeof value, `${key} must be a string`).toBe('string');
    }
  });
});

describe('Node re-derives the same canonical bytes as Python', () => {
  it.each(vectors.map((v) => [v.name, v]))('%s', (_name, v) => {
    expect(canonical(v.payment)).toBe(v.canonical);
  });
});

describe('Node re-derives the same SHA-256 as Python', () => {
  it.each(vectors.map((v) => [v.name, v]))('%s', (_name, v) => {
    expect(sha256Hex(v.canonical)).toBe(v.sha256);
  });
});

describe('the canonical form obeys its own rules', () => {
  it.each(vectors.map((v) => [v.name, v]))('%s', (_name, v) => {
    const text = v.canonical;

    // No whitespace between tokens. Any space must be inside a quoted string,
    // so counting spaces outside strings is the honest check.
    const outsideStrings = text.replace(/"(?:[^"\\]|\\.)*"/g, '""');
    expect(outsideStrings).not.toMatch(/\s/);

    expect(text.startsWith('{')).toBe(true);
    expect(text.endsWith('}')).toBe(true);

    // Keys appear in sorted order.
    const keysInOrder = [...text.matchAll(/"([a-z0-9_]+)":/g)].map((m) => m[1]);
    const keyNames = keysInOrder.filter((k) => FIELDS.includes(k));
    expect(keyNames).toEqual([...keyNames].sort());

    // Round-trips as JSON, and every parsed value is a string.
    const parsed = JSON.parse(text);
    for (const value of Object.values(parsed)) {
      expect(typeof value).toBe('string');
    }
  });

  it('records the byte length that UTF-8 actually produces', () => {
    for (const v of vectors) {
      expect(Buffer.byteLength(v.canonical, 'utf8')).toBe(v.canonical_utf8_bytes);
    }
  });

  it('emits non-ASCII characters raw, never as \\uXXXX escapes', () => {
    const tamil = vectors.find((v) => v.name === 'tamil_payee_name');
    expect(tamil.canonical).not.toContain('\\u0b');
    expect(tamil.canonical).toContain('ஸ'); // the actual Tamil letter
  });
});

describe('the traps these vectors exist to catch', () => {
  it('NFC: a decomposed name hashes identically to the composed one', () => {
    const composed = vectors.find((v) => v.name === 'nfc_already_composed');
    const decomposed = vectors.find((v) => v.name === 'nfc_decomposed_input');

    // The inputs really are different, or the test proves nothing.
    expect(decomposed.payment.payee_name).not.toBe(composed.payment.payee_name);
    // And the outputs really are identical.
    expect(decomposed.canonical).toBe(composed.canonical);
    expect(decomposed.sha256).toBe(composed.sha256);
  });

  it('leading zeros on an account number survive into the bytes', () => {
    const v = vectors.find((v) => v.name === 'account_with_leading_zeros');
    expect(v.payment.payee_account).toMatch(/^0{6}/);
    expect(v.canonical).toContain('"payee_account":"000000045210"');
  });

  it('a crore-sized amount stays exact', () => {
    const v = vectors.find((v) => v.name === 'crore_sized_amount');
    expect(v.canonical).toContain('"amount_paise":"10400000000"');
    // Beyond what a 32-bit integer holds, which is why it is a string.
    expect(BigInt(v.payment.amount_paise)).toBeGreaterThan(2147483647n);
  });

  it('the full payee account is signed, not the masked last four', () => {
    for (const v of vectors) {
      expect(v.payment.payee_account.length).toBeGreaterThan(4);
      expect(v.canonical).toContain(`"payee_account":"${v.payment.payee_account}"`);
    }
  });

  it('quotes and backslashes are escaped the standard way', () => {
    const v = vectors.find((v) => v.name === 'name_needing_json_escapes');
    expect(v.canonical).toContain('\\"Lakshmi\\"');
    expect(v.canonical).toContain('\\\\');
    expect(JSON.parse(v.canonical).payee_name).toBe(v.payment.payee_name);
  });

  it('ampersand and slash are left raw, not escaped', () => {
    const v = vectors.find((v) => v.name === 'ampersand_and_slash_in_purpose');
    expect(v.canonical).toContain('INV-2219/A & B');
    expect(v.canonical).not.toContain('\\/');
    expect(v.canonical).not.toContain('\\u0026');
  });

  it('sorting by code unit matches sorting by code point for these field names', () => {
    // JavaScript sorts strings by UTF-16 code unit, Python by code point. They
    // differ only above the BMP, and every field name here is lower-case ASCII,
    // so the two agree. Pinned so that adding an exotic field name fails loudly.
    for (const field of FIELDS) {
      expect(field).toMatch(/^[a-z0-9_]+$/);
    }
  });
});
